using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NpcContinuingTests
{
    static readonly string[] Places=["site:castle","site:kofu","site:odawara","site:fork","site:village"];
    internal static ContractWorld Start(int count=2,bool companions=false){var records=NewGameWorld.Normalize(Enumerable.Range(0,count).Select(n=>NewGameWorldTests.Officer("created:routine-"+n,site:Places[n%Places.Length])).ToArray());var raw=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var request=new WorldSetupRequest(records,[]);var setup=NewGameSetup.Confirm(raw,request,NewGameSetup.Preview(raw,request));return NewGameWorld.Create(setup,records,"person:nobunaga",20261030,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.ContinuingPolicy,LocalInspectionFindings.Policy,WorkFollowup.Policy,LocalWorkDemand.Policy,developmentPolicy:CharacterDevelopment.Policy,companionPolicy:companions?PersonalCompanions.Policy:null);}
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    [Fact]public void RegisteredAdultsAndHistoricalActorsUseOwnSharedTasks(){var s=new WorldSession(Start());At(s,20);var w=s.DiagnosticSnapshot();Assert.Equal(7,w.Requests.Length);Assert.All(w.Tasks,t=>Assert.Equal(ExecutionPhase.Completed,t.Execution));Assert.DoesNotContain(w.Requests,r=>r.Intent.Actor==s.PlayerControl);Assert.Contains(w.Requests,r=>r.Intent.Actor.Value=="created:routine-0");Assert.Empty(s.GetActorView(s.PlayerControl).Messages);Assert.Contains(w.Development!.Awards,a=>a.Actor.Value=="created:routine-0"&&a.Experience>0);new WorldSession(w);}
    [Fact]public void DailyWorkRequiresOwnStaleRecordsAndDoesNotRepeatEveryTick(){var s=new WorldSession(Start());At(s,20);int first=s.DiagnosticSnapshot().Requests.Length;At(s,3601);Assert.Equal(first,s.DiagnosticSnapshot().Requests.Length);At(s,86420);Assert.Equal(first*2,s.DiagnosticSnapshot().Requests.Length);At(s,172820);Assert.Equal(first*3,s.DiagnosticSnapshot().Requests.Length);Assert.All(s.DiagnosticSnapshot().Requests.GroupBy(r=>r.Intent.Actor),g=>Assert.All(g.Zip(g.Skip(1)),x=>Assert.True(x.Second.CreatedAt-x.First.CreatedAt>=86400)));}
    [Fact]public void FreshPersonalObservationsAvoidUnneededDailyInspection(){var s=new WorldSession(Start());At(s,86390);var actor=new EntityId("created:routine-0");var w=s.DiagnosticSnapshot();foreach(var e in BranchRoutes.GraphEdges(w).Where(e=>e.From=="castle"||e.To=="castle"))Assert.Equal(ResultCode.Accepted,s.InspectRoad(actor,e.Id,s.Revision).Code);int count=w.Requests.Count(r=>r.Intent.Actor==actor);At(s,86420);Assert.Equal(count,s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Actor==actor));At(s,90020);Assert.Equal(count+1,s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Actor==actor));}
    [Fact]public void HiddenRoadClosureCannotChangeTheInitialDecision(){var a=Start();var b=ContractJson.Copy(a);string edge=BranchRoutes.GraphEdges(a).First(e=>e.From=="castle"||e.To=="castle").Id;b.Couriers=b.Couriers! with{Conditions=[new(1,edge,true)]};var x=new WorldSession(a);var y=new WorldSession(b);At(x,1);At(y,1);Assert.Equal(ContractJson.Write(x.DiagnosticSnapshot().NpcWork),ContractJson.Write(y.DiagnosticSnapshot().NpcWork));At(x,20);At(y,20);var actor=new EntityId("created:routine-0");Assert.DoesNotContain(x.DiagnosticSnapshot().Evidence,e=>e.Observer==actor&&e.Claim=="route-block:"+edge);Assert.Contains(y.DiagnosticSnapshot().Evidence,e=>e.Observer==actor&&e.Claim=="route-block:"+edge);}
    [Fact]public void HeldPersonCannotInspectUntilPhysicallyReleased(){var s=CustodySuccessionTests.Held(NewGameNpcRoutine.ContinuingPolicy);var ward=new EntityId("created:ward");int n=s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Actor==ward);At(s,s.Seconds+86400);Assert.Equal(n,s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Actor==ward));Assert.False(NewGameNpcRoutine.Inputs(s.DiagnosticSnapshot(),ward,s.Seconds,s.Revision).InspectionPermit);var root=s.DiagnosticSnapshot().Custody!.Entries.First().Input.Id;Assert.Equal(ResultCode.Accepted,s.ManageCustody(new(new("request:npc-release"),CustodyAction.Release,Original:root),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+20);Assert.Equal(n+1,s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Actor==ward));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void InsufficientBudgetLeavesTheWholeGenerationUntouched(){var s=new WorldSession(Start(12));s.SetPaused(false);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal("EventBudget",s.AdvanceTo(1,1).StopReason);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));At(s,20);Assert.Equal(17,s.DiagnosticSnapshot().Tasks.Length);}
    [Fact]public void MinorAndPlayerNeverReceiveAutonomousTasks(){var original=Start();var data=original.NewGame!;var records=NewGameWorld.Normalize([..data.Registered,NewGameWorldTests.Officer("created:minor") with{BirthYear=1550}]);var raw=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var req=new WorldSetupRequest(records,[]);var setup=NewGameSetup.Confirm(raw,req,NewGameSetup.Preview(raw,req));var s=new WorldSession(NewGameWorld.Create(setup,records,"person:nobunaga",20261030,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.ContinuingPolicy,LocalInspectionFindings.Policy,WorkFollowup.Policy,LocalWorkDemand.Policy));At(s,20);Assert.DoesNotContain(s.DiagnosticSnapshot().Requests,r=>r.Intent.Actor.Value=="created:minor"||r.Intent.Actor==s.PlayerControl);}
    [Fact]public void ContinuingPolicyNeedsItsObservationRules(){var w=Start();w.NewGame=w.NewGame! with{DemandPolicy=null};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void DecisionEvidenceCannotBeForged(){var s=new WorldSession(Start());At(s,20);var w=s.DiagnosticSnapshot();var d=w.NpcWork!.Decisions[0];w.NpcWork.Decisions[0]=d with{Inputs=d.Inputs with{Routine=d.Inputs.Routine! with{Need=d.Inputs.Routine!.Need! with{Needed=false}}}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ActualActivePopulationUsesMultipleNationalSites(){var timer=System.Diagnostics.Stopwatch.StartNew();var s=new WorldSession(Start(24));At(s,20);timer.Stop();var w=s.DiagnosticSnapshot();Assert.Equal(29,w.Tasks.Length);Assert.All(w.Tasks,t=>Assert.Equal(ExecutionPhase.Completed,t.Execution));Assert.True(w.Tasks.Select(t=>t.Scope).Distinct().Count()>=5);var folder=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(folder))File.WriteAllText(Path.Combine(folder,"npc-continuing-active-population-measurement.txt"),$"Active NPCs=29; registered=24; shared clock=20 seconds; measured wall milliseconds={timer.ElapsedMilliseconds}; product 3000/1000/500 and FPS not verified.");}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]
    public void ActualGenerationRecoveryKeepsOwnInputsAndFuture(int phase){var s=new WorldSession(Start());At(s,phase switch{0=>1,1=>3,2=>20,3=>86403,_=>86420});s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"npc-continuing-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"npc",w.WorldId).Published);var host=new WorldSessionHost(new WorldSession(Start()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("npc"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,$"npc-continuing-{phase}.before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,$"npc-continuing-{phase}.restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+20);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}

    [Fact]public void UnreceivedOwnReportPreventsNewAutonomousWork(){var s=new WorldSession(Start());At(s,6);var actor=new EntityId("created:routine-0");var report=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="contract-report"&&m.RecipientId==actor.Value);s.DiagnosticTransport((m,t)=>HakutaiKagami.Core.Messaging.MessageFlow.Fail(m,report.Id));At(s,86420);Assert.Single(s.DiagnosticSnapshot().Requests,r=>r.Intent.Actor==actor);Assert.False(NewGameNpcRoutine.Inputs(s.DiagnosticSnapshot(),actor,s.Seconds,s.Revision).LastReportKnown);}
    [Fact]public void ActualCompanionTravelBlocksAutonomousWorkAndResumesAtNewSite(){var s=new WorldSession(Start(companions:true));var actor=new EntityId("created:routine-0");Assert.Equal(ResultCode.Accepted,s.ManageCompanion(new(new("request:npc-agree"),actor,CompanionAction.Agree,Amount:20),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.ManageCompanion(new(new("request:npc-walk"),actor,CompanionAction.TravelTogether,Destination:"kofu"),s.PlayerControl,s.Revision).Code);At(s,20);Assert.DoesNotContain(s.DiagnosticSnapshot().Requests,r=>r.Intent.Actor==actor&&r.Intent.Action==ActionKind.Inspect);long arrival=s.DiagnosticSnapshot().Branches!.Journeys.Max(j=>j.Legs[^1].EndAt);At(s,arrival+20);Assert.Contains(s.DiagnosticSnapshot().Requests,r=>r.Intent.Actor==actor&&r.Intent.Action==ActionKind.Inspect&&r.Intent.Scope==new EntityId("site:kofu"));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void NewProfilePinsPolicyAndActualInitialHash(){var w=Start();var d=w.NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"npc-continuing-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(d.Start,d.Registered,d.Selected.Value,w.Seed,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.ContinuingPolicy,LocalInspectionFindings.Policy,WorkFollowup.Policy,LocalWorkDemand.Policy,developmentPolicy:CharacterDevelopment.Policy);Assert.Equal(NewGameNpcRoutine.ContinuingPolicy,store.Read(p.Instance).NpcRoutinePolicy);Assert.Equal(ContractJson.Write(w),ContractJson.Write(NewCampaignStore.Build(p)));Assert.Throws<InvalidDataException>(()=>NewCampaignStore.Build(p with{NpcRoutinePolicy=NewGameNpcRoutine.Policy}));}

}
